function cell(ctx,x,y,w,h){const left=Math.round(x),top=Math.round(y),right=Math.round(x+w),bottom=Math.round(y+h);if(right>left&&bottom>top)ctx.fillRect(left,top,right-left,bottom-top);}

/** 5x7 bitmap glyphs. Coordinates name the top edge; unknown characters render '?'. */
export function pixelText(ctx,value,x,y,color,scale=1,options={}){
  const unit=Number.isFinite(scale)&&scale>0?scale:1;
  const lines=String(value??'').split('\n');let widest=0;
  ctx.fillStyle=color;
  lines.forEach((line,rowIndex)=>{
    let chars=[...line];const max=Number(options.maxWidth);
    if(Number.isFinite(max)&&max>=0){const count=Math.max(0,Math.floor((max/unit+1)/6));if(chars.length>count)chars=count>=3?[...chars.slice(0,count-3),'.','.','.']:chars.slice(0,count);}
    const width=chars.length?((chars.length*6-1)*unit):0;widest=Math.max(widest,width);
    let cursor=x-(options.align==='center'?width/2:options.align==='right'?width:0);
    for(const character of chars){const bitmap=FONT[character]||FONT['?'];for(let row=0;row<7;row++)for(let column=0;column<5;column++)if(bitmap[row][column]==='1')cell(ctx,cursor+column*unit,y+(rowIndex*9+row)*unit,unit,unit);cursor+=6*unit;}
  });
  return {width:widest,height:lines.length?(lines.length*9-2)*unit:0};
}

/** Discrete markers; x/y is the marker's top-left, and every mark fits size x size. */
export function glyphMark(ctx,x,y,mark,color,size=4){
  const n=Math.max(1,Math.round(Number.isFinite(size)?size:4));ctx.fillStyle=color;
  if(mark==='blocks'){cell(ctx,x,y,n,n);return;}
  if(mark==='lines'){const stroke=Math.max(1,Math.floor(n/5));for(let row=0;row<n;row+=stroke+1)cell(ctx,x,y+row,n,Math.min(stroke,n-row));return;}
  if(mark==='hashes'){
    const bitmap=['01010','11111','01010','11111','01010'];for(let row=0;row<5;row++)for(let col=0;col<5;col++)if(bitmap[row][col]==='1')cell(ctx,x+col*n/5,y+row*n/5,n/5,n/5);return;
  }
  const width=Math.max(1,Math.round(n*.45)),offset=Math.floor((n-width)/2);cell(ctx,x+offset,y+offset,width,width);
}

/** Square pixel border, optional double rule, solid fill or repeated marker fill. */
export function glyphRect(ctx,x,y,w,h,color,options={}){
  const left=Math.round(x),top=Math.round(y),width=Math.max(1,Math.round(w)),height=Math.max(1,Math.round(h));
  const inset=options.double?4:2;
  if(options.fill){
    ctx.fillStyle=typeof options.fill==='string'?options.fill:color;
    if(options.mark){for(let yy=top+inset;yy+4<=top+height-inset;yy+=6)for(let xx=left+inset;xx+4<=left+width-inset;xx+=6)glyphMark(ctx,xx,yy,options.mark,ctx.fillStyle,4);}
    else if(width>inset*2&&height>inset*2)cell(ctx,left+inset,top+inset,width-inset*2,height-inset*2);
  }
  ctx.fillStyle=color;
  cell(ctx,left,top,width,1);cell(ctx,left,top+height-1,width,1);cell(ctx,left,top,1,height);cell(ctx,left+width-1,top,1,height);
  if(options.double&&width>=9&&height>=9){cell(ctx,left+3,top+3,width-6,1);cell(ctx,left+3,top+height-4,width-6,1);cell(ctx,left+3,top+3,1,height-6);cell(ctx,left+width-4,top+3,1,height-6);}
}
